<body>
<div class="app">
  <h1>Things <span>to&nbsp;do</span></h1>
  <div class="card">
    <div class="input-row">
      <input id="todo-input" type="text" placeholder="What needs to be done?" autocomplete="off" maxlength="300">
      <button id="add-btn" title="Add todo" aria-label="Add todo">+</button>
    </div>
    <ul id="todo-list"></ul>
    <div class="empty" id="empty-msg" hidden></div>
    <div class="footer">
      <span class="count" id="count"></span>
      <div class="filters">
        <button class="filter-btn active" data-filter="all">All</button>
        <button class="filter-btn" data-filter="active">Active</button>
        <button class="filter-btn" data-filter="completed">Completed</button>
      </div>
      <button class="clear-btn" id="clear-btn">Clear completed</button>
    </div>
  </div>
</div>
<script>
(function () {
  'use strict';

  var STORAGE_KEY = 'todo_ollama-mimo-v2.6-flash-rl-mxfp4_01';
  var todos = [];
  var filter = 'all';

  var input = document.getElementById('todo-input');
  var addBtn = document.getElementById('add-btn');
  var list = document.getElementById('todo-list');
  var emptyMsg = document.getElementById('empty-msg');
  var countEl = document.getElementById('count');
  var clearBtn = document.getElementById('clear-btn');
  var filterBtns = document.querySelectorAll('.filter-btn');

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        var parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) {
          todos = parsed.filter(function (t) {
            return t && typeof t.text === 'string' && typeof t.completed === 'boolean';
          });
        }
      }
    } catch (e) {
      todos = [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch (e) { /* storage unavailable — keep in memory */ }
  }

  function addTodo() {
    var text = input.value.trim();
    if (!text) return;
    todos.push({
      id: Date.now().toString(36) + Math.random().toString(36).slice(2, 7),
      text: text,
      completed: false
    });
    input.value = '';
    save();
    render();
    input.focus();
  }

  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    save();
    render();
  }

  function deleteTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    save();
    render();
  }

  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    save();
    render();
  }

  function visibleTodos() {
    if (filter === 'active') return todos.filter(function (t) { return !t.completed; });
    if (filter === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function render() {
    var visible = visibleTodos();
    list.innerHTML = '';

    visible.forEach(function (todo) {
      var li = document.createElement('li');
      li.className = 'todo' + (todo.completed ? ' completed' : '');

      var cb = document.createElement('span');
      cb.className = 'checkbox';
      cb.setAttribute('role', 'checkbox');
      cb.setAttribute('aria-checked', String(todo.completed));
      cb.setAttribute('aria-label', 'Toggle "' + todo.text + '"');
      cb.textContent = '✓';
      cb.addEventListener('click', function () { toggleTodo(todo.id); });

      var span = document.createElement('span');
      span.className = 'todo-text';
      span.textContent = todo.text;
      span.addEventListener('click', function () { toggleTodo(todo.id); });

      var del = document.createElement('button');
      del.className = 'delete-btn';
      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
      del.textContent = '×';
      del.addEventListener('click', function () { deleteTodo(todo.id); });

      li.appendChild(cb);
      li.appendChild(span);
      li.appendChild(del);
      list.appendChild(li);
    });

    var messages = {
      all: 'No todos yet — add one above!',
      active: 'No active todos. 🎉',
      completed: 'Nothing completed yet.'
    };
    if (visible.length === 0) {
      emptyMsg.textContent = messages[filter];
      emptyMsg.hidden = false;
    } else {
      emptyMsg.hidden = true;
    }

    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    countEl.textContent = activeCount + (activeCount === 1 ? ' item left' : ' items left');

    clearBtn.style.visibility = todos.some(function (t) { return t.completed; })
      ? 'visible' : 'hidden';
  }

  function setFilter(next) {
    filter = next;
    filterBtns.forEach(function (btn) {
      btn.classList.toggle('active', btn.dataset.filter === filter);
    });
    render();
  }

  addBtn.addEventListener('click', addTodo);
  input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') addTodo();
  });
  clearBtn.addEventListener('click', clearCompleted);
  filterBtns.forEach(function (btn) {
    btn.addEventListener('click', function () { setFilter(btn.dataset.filter); });
  });

  load();
  render();
})();
</script>
